    /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' (errno_addr tp) [C4 (rg_errno a errv)]
    /\ rw_cells usegs m' RPAGE_SIZE [C8 (Z_to_bv 64 4096)]
